import * as THREE from 'three/webgpu';
import {
    uv,
    texture,
    vec2,
    MeshBasicNodeMaterial,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
    // Root container
    const root = new THREE.Object3D();

    // Apply cinematic primitives if any
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const primitive of config.cinematicPrimitives) {
            const fn = ctx.primitives?.[primitive.name];
            if (typeof fn === 'function') {
                fn(root, primitive.params);
            }
        }
    }

    // -----------------------------------------------------------------
    // Texture & Atlas handling (sprite / billboard)
    // -----------------------------------------------------------------
    const imageUrl = config.assets?.imageUrl ?? '';
    const mapTexture = ctx.textureLoader(imageUrl);
    mapTexture.wrapS = mapTexture.wrapT = THREE.RepeatWrapping;
    mapTexture.needsUpdate = true;

    // Atlas region (fallback to full texture)
    const rect = (config.atlas && config.atlas.srcRect) ? {
        x: config.atlas.srcRect.x ?? 0,
        y: config.atlas.srcRect.y ?? 0,
        width: config.atlas.srcRect.width ?? mapTexture.image?.width ?? 1,
        height: config.atlas.srcRect.height ?? mapTexture.image?.height ?? 1,
    } : {
        x: 0,
        y: 0,
        width: mapTexture.image?.width ?? 1,
        height: mapTexture.image?.height ?? 1,
    };

    const texW = mapTexture.image?.width ?? 1;
    const texH = mapTexture.image?.height ?? 1;

    const repeatX = rect.width / texW;
    const repeatY = rect.height / texH;
    const offsetX = rect.x / texW;
    const offsetY = 1 - (rect.y + rect.height) / texH; // UV origin is bottom‑left

    const uvNode = uv()
        .mul(vec2(repeatX, repeatY))
        .add(vec2(offsetX, offsetY));

    const mapNode = texture(mapTexture, uvNode);

    const material = new MeshBasicNodeMaterial({
        map: mapNode,
        transparent: true,
        depthTest: true,
        depthWrite: false,
    });

    // Plane geometry respecting the atlas aspect ratio
    const aspect = rect.width / rect.height;
    const geometry = new THREE.PlaneGeometry(aspect, 1);

    const mesh = new THREE.Mesh(geometry, material);
    mesh.renderOrder = 0;

    // Billboard: always face the camera
    mesh.onBeforeRender = (renderer, scene, camera) => {
        mesh.quaternion.copy(camera.quaternion);
    };

    root.add(mesh);

    // -----------------------------------------------------------------
    // Transform (position / rotation / scale) from config
    // -----------------------------------------------------------------
    const pos = config.position ?? [0, 0, 0];
    const rot = config.rotation ?? [0, 0, 0];
    const scl = config.scale ?? [1, 1, 1];

    root.position.set(pos[0], pos[1], pos[2]);
    root.rotation.set(rot[0], rot[1], rot[2]);
    root.scale.set(scl[0], scl[1], scl[2]);

    // -----------------------------------------------------------------
    // Cleanup & handlers storage
    // -----------------------------------------------------------------
    const timelines = [];

    root.userData = {
        handlers: {},
        // Allows external code to dispose all resources
        cleanup() {
            geometry.dispose();
            material.dispose();
            if (mapTexture && typeof mapTexture.dispose === 'function') {
                // Dispose only if we own the texture (cached textures may ignore)
                mapTexture.dispose();
            }
            // Kill any GSAP timelines that might have been stored
            timelines.forEach(tl => tl.kill());
        },
    };

    // Example placeholder for potential GSAP timeline usage
    // const tl = gsap.to(mesh.scale, { x: 1.1, y: 1.1, duration: 0.6, repeat: -1, yoyo: true });
    // timelines.push(tl);

    return root;
}
